const svcLd = (name, url, desc, offers = []) => ({ '@context': 'https://schema.org', '@type': 'Service', name, description: desc, url: SITE.url + url, provider: { '@id': SITE.url + '/#salon' }, areaServed: 'Paris 12', ...(offers.length ? { offers: offers.map(o => ({ '@type': 'Offer', name: o[0], price: String(o[1]), priceCurrency: 'EUR', url: SITE.url + url })) } : {}) });
