  + sec(`<div class="grid g2"><div>${head('Inclus', 'Ce qui vous attend')}<ul class="checks"><li>Le jacuzzi Gloria, 100 buses de massage</li><li>Une douche multi-jets</li><li>Un espace détente avec bar</li><li>Les rituels La Sultane de Saba, mis à disposition pour prolonger l’expérience</li><li>Serviettes et peignoirs ${PH}</li></ul></div><div>${head('Pratique', 'Arrivée et durée')}<p>Arrivée 10 minutes avant le créneau ${PH}. Annulation ${PH}.</p></div></div>`)
  + imm(photo('jacuzzi-privatif-ambiance-paris-12', "Jacuzzi privatif aux bulles lumineuses, bougies, orchidées et champagne, institut Sophie B Paris 12", { sizes: '100vw' }), `<p class="eyebrow">Offrir</p><h2>Une expérience à vivre <em>ou à offrir</em></h2><p>À offrir ou à s’offrir, cette expérience est bien plus qu’un cadeau : c’est une invitation au lâcher-prise, au bien-être et au plaisir des sens.</p><p>Anniversaire, moment romantique, célébration, surprise ou simple envie de se retrouver… cette parenthèse d’exception crée des souvenirs inoubliables et transforme chaque instant en expérience précieuse.</p><p>Dans cet univers hors du temps, tout est pensé pour ralentir, respirer et savourer pleinement l’instant présent.</p><p><a class="btn" href="/carte-cadeau/">Offrir un moment</a></p>`, 'r')
